import os
import errno
import sys
import logging
import select
try:
    import SocketServer
except ImportError:
    import socketserver as SocketServer
import threading
from taf.internal.managedobject import ManagedObject


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())

RECEIVED_MAX_BYTES = 2 ** 16


class Handler(SocketServer.BaseRequestHandler):

    def handle(self):
        channel = self.server._ssh_forwarding.create_channel()
        logger.debug(f"you can get the remote service by connecting to address {self.server.server_address}")

        exit_readfd = self._create_exit_pipe()

        while True:
            rlist, _, _ = select.select([self.request, channel, exit_readfd], [], [])
            source = "unknown"
            try:
                if self.request in rlist:
                    source = "request"
                    data = self.request.recv(RECEIVED_MAX_BYTES)
                    if not data:
                        logger.debug(f"{source} recv empty, exit handler")
                        break
                    channel.send(data)

                if channel in rlist:
                    source = "channel"
                    data = channel.recv(RECEIVED_MAX_BYTES)
                    if not data:
                        logger.debug(f"{source} recv empty, exit handler")
                        break
                    self.request.send(data)
            except ConnectionResetError as err:
                logger.debug(f"{source.capitalize()} connection was reset: {err}")
                break

            if exit_readfd in rlist:
                recv_bytes = os.read(exit_readfd, RECEIVED_MAX_BYTES)
                if recv_bytes:
                    logger.debug("receive exit message, exit handler")
                    break



        os.close(exit_readfd)
        channel.close()
        self.request.close()
        logger.debug("handler has been stopped")

    def _create_exit_pipe(self):
        readfd, writefd = os.pipe()
        self.server.add_handler_exit_pipe(writefd)
        return readfd


class Server(SocketServer.ThreadingTCPServer):

    daemon_threads = False
    allow_reuse_address = True

    block_on_close = True
    _threads = None

    def __init__(self, ssh_forwarding, **kwargs):
        SocketServer.ThreadingTCPServer.__init__(self, **kwargs)
        self._ssh_forwarding = ssh_forwarding

        self._lock = threading.Lock()

        self._handler_exit_writefds = []

    def add_handler_exit_pipe(self, pipe_writer):
        self._lock.acquire()
        self._handler_exit_writefds.append(pipe_writer)
        self._lock.release()

    def close_handlers(self):
        for writefd in self._handler_exit_writefds:
            try:
                os.write(writefd, b"exit")
            except OSError as err:
                if err.errno != errno.EPIPE:
                    raise

            os.close(writefd)

    def process_request(self, request, client_address):
        if sys.version_info.major == 2:
            """Start a new thread to process the request."""
            t = threading.Thread(target=self.process_request_thread,
                                 args=(request, client_address))
            t.daemon = self.daemon_threads
            if not t.daemon and self.block_on_close:
                if self._threads is None:
                    self._threads = []
                self._threads.append(t)
            t.start()
        else:
            super(Server, self).process_request(request, client_address)

    def server_close(self):
        if sys.version_info.major == 2:
            if self.block_on_close:
                threads = self._threads
                self._threads = None
                if threads:
                    for thread in threads:
                        thread.join()
            SocketServer.ThreadingTCPServer.server_close(self)
        else:
            super().server_close()

        logger.info("all server's threads stopped successfully")


class ForwardingServer(ManagedObject):
    def __init__(self, ssh_forwarding, server_address, **kwargs):
        super(ForwardingServer, self).__init__(**kwargs)
        self._ssh_forwarding = ssh_forwarding
        self._server_address = server_address
        self.add_prerequisite(ssh_forwarding)

        self._thread = None
        self._server = None

    def _setup(self):
        self._server = Server(ssh_forwarding=self._ssh_forwarding, RequestHandlerClass=Handler, server_address=self._server_address)
        self._server_address = self._server.server_address
        logger.debug(f"setup forwarding server with server address={self._server_address}")

        self._thread = threading.Thread(target=self._server.serve_forever)
        self._thread.daemon = True
        self._thread.start()
        logger.debug("startup forwarding server successfully")

    def _teardown(self):
        self._shutdown_handlers()
        self._server.shutdown()
        self._server.server_close()
        self._thread.join()
        logger.debug("teardown forwarding server successfully")

    def _shutdown_handlers(self):
        self._server.close_handlers()
        logger.debug("shutdown all handlers")

    @property
    def host(self):
        return self._server_address[0]

    @property
    def port(self):
        return self._server_address[1]
